import { describe, expect, it } from "vitest";

import { parsePasswd, renderUnit } from "./unit.js";

describe("renderUnit", () => {
  const params = {
    user: "jarrin",
    uid: 1000,
    home: "/home/jarrin",
    bin: "/home/jarrin/.local/bin/claudjar",
    confPath: "/etc/claudjar.conf",
  };

  it("renders a system unit running as the conf user", () => {
    expect(renderUnit(params)).toBe(
      [
        "# Generated by `claudjar service install` — rerun it instead of editing.",
        "[Unit]",
        "Description=claudjar service (projects, background Claude sessions)",
        "Wants=network-online.target",
        "After=network-online.target",
        "",
        "[Service]",
        "Type=simple",
        "User=jarrin",
        "WorkingDirectory=/home/jarrin",
        'Environment="HOME=/home/jarrin"',
        'Environment="XDG_RUNTIME_DIR=/run/user/1000"',
        'Environment="PATH=/home/jarrin/.local/bin:/usr/local/sbin:/usr/local/bin:/usr/bin"',
        'Environment="CLAUDJAR_CONF=/etc/claudjar.conf"',
        "ExecStart=/home/jarrin/.local/bin/claudjar service run",
        "Restart=on-failure",
        "RestartSec=5",
        "",
        "[Install]",
        "WantedBy=multi-user.target",
        "",
      ].join("\n"),
    );
  });

  it("keeps the default KillMode (sessions live in their own scope)", () => {
    expect(renderUnit(params)).not.toMatch(/KillMode/);
  });

  it("quotes paths with spaces and escapes systemd specifiers", () => {
    const unit = renderUnit({
      ...params,
      home: "/home/a b",
      bin: "/opt/c%d/claudjar",
    });
    expect(unit).toContain('WorkingDirectory="/home/a b"');
    expect(unit).toContain("ExecStart=/opt/c%%d/claudjar service run");
    expect(unit).toContain('Environment="HOME=/home/a b"');
  });
});

describe("parsePasswd", () => {
  it("parses a getent row", () => {
    expect(
      parsePasswd("jarrin:x:1000:1000:Jarrin:/home/jarrin:/bin/zsh\n"),
    ).toEqual({
      user: "jarrin",
      uid: 1000,
      home: "/home/jarrin",
    });
  });

  it("rejects anything else", () => {
    expect(parsePasswd("")).toBeNull();
    expect(parsePasswd("jarrin:x:abc:1000::/home/jarrin:/bin/zsh")).toBeNull();
  });
});
